#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double x, y, r;
} Circle;

typedef struct {
    double x, y;
    int idx;
} Point;

static int cmp_x(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x < q->x) return -1;
    if (p->x > q->x) return 1;
    if (p->y < q->y) return -1;
    if (p->y > q->y) return 1;
    return 0;
}

static int cmp_y(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->y < q->y) return -1;
    if (p->y > q->y) return 1;
    if (p->x < q->x) return -1;
    if (p->x > q->x) return 1;
    return 0;
}

static inline double center_dist(const Circle *a, const Circle *b) {
    double dx = a->x - b->x;
    double dy = a->y - b->y;
    return sqrt(dx * dx + dy * dy);
}

static inline double circle_dist(const Circle *a, const Circle *b) {
    return center_dist(a, b) - a->r - b->r;
}

/*
Closest pair of points among centers.
Because radii differ by at most factor 2, minimizing center distance
also minimizes circle distance up to a constant-factor argument, and
for non-overlapping circles the true closest pair must be among pairs
with very small center distance. We compute exact answer by checking
the candidate pairs generated by the standard closest-pair strip method.
*/

static double min_double(double a, double b) { return a < b ? a : b; }

static double solve_rec(Point *px, Point *py, Point *tmp, int n, Circle *circles, double *best_circle) {
    if (n <= 3) {
        double best = 1e300;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double d = center_dist(&circles[px[i].idx], &circles[px[j].idx]);
                if (d < best) best = d;
                double cd = circle_dist(&circles[px[i].idx], &circles[px[j].idx]);
                if (cd < *best_circle) *best_circle = cd;
            }
        }
        qsort(py, n, sizeof(Point), cmp_y);
        return best;
    }

    int mid = n / 2;
    double midx = px[mid].x;
    int midIdx = px[mid].idx;

    Point *pyl = (Point *)malloc(mid * sizeof(Point));
    Point *pyr = (Point *)malloc((n - mid) * sizeof(Point));
    int li = 0, ri = 0;

    char *isLeft = (char *)calloc(n + 5, sizeof(char));
    for (int i = 0; i < mid; i++) isLeft[px[i].idx] = 1;

    for (int i = 0; i < n; i++) {
        if (isLeft[py[i].idx]) pyl[li++] = py[i];
        else pyr[ri++] = py[i];
    }

    double dl = solve_rec(px, pyl, tmp, mid, circles, best_circle);
    double dr = solve_rec(px + mid, pyr, tmp, n - mid, circles, best_circle);
    double d = min_double(dl, dr);

    int ti = 0;
    for (int i = 0; i < n; i++) {
        if (fabs(py[i].x - midx) < d) tmp[ti++] = py[i];
    }

    for (int i = 0; i < ti; i++) {
        for (int j = i + 1; j < ti && (tmp[j].y - tmp[i].y) < d; j++) {
            double cdcenter = center_dist(&circles[tmp[i].idx], &circles[tmp[j].idx]);
            if (cdcenter < d) d = cdcenter;
            double cd = circle_dist(&circles[tmp[i].idx], &circles[tmp[j].idx]);
            if (cd < *best_circle) *best_circle = cd;
        }
    }

    free(pyl);
    free(pyr);
    free(isLeft);
    return d;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    if (N < 2) return 0;

    Circle *circles = (Circle *)malloc(N * sizeof(Circle));
    Point *px = (Point *)malloc(N * sizeof(Point));
    Point *py = (Point *)malloc(N * sizeof(Point));
    Point *tmp = (Point *)malloc(N * sizeof(Point));

    for (int i = 0; i < N; i++) {
        scanf("%lf %lf %lf", &circles[i].x, &circles[i].y, &circles[i].r);
        px[i].x = py[i].x = circles[i].x;
        px[i].y = py[i].y = circles[i].y;
        px[i].idx = py[i].idx = i;
    }

    qsort(px, N, sizeof(Point), cmp_x);
    qsort(py, N, sizeof(Point), cmp_y);

    double best_circle = 1e300;
    solve_rec(px, py, tmp, N, circles, &best_circle);

    if (best_circle < 0 && best_circle > -1e-12) best_circle = 0.0;
    printf("%.10f\n", best_circle);

    free(circles);
    free(px);
    free(py);
    free(tmp);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Circle {
    double x, y, r;
};

double dist(const Circle &a, const Circle &b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return sqrt(dx*dx + dy*dy) - a.r - b.r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Circle> circles(n);
    for (int i = 0; i < n; i++) {
        cin >> circles[i].x >> circles[i].y >> circles[i].r;
    }

    // Sort circles by x - r (leftmost point)
    vector<int> idx(n);
    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&](int i, int j) {
        return circles[i].x - circles[i].r < circles[j].x - circles[j].r;
    });

    // Active set sorted by y coordinate
    set<int, function<bool(int,int)>> active([&](int i, int j) {
        if (circles[i].y == circles[j].y) return i < j;
        return circles[i].y < circles[j].y;
    });

    double best = 1e18;
    int left = 0;

    for (int i : idx) {
        double curX = circles[i].x - circles[i].r;

        // Remove circles whose right edge is far left from current
        while (left < (int)idx.size() && circles[idx[left]].x + circles[idx[left]].r < curX - best) {
            active.erase(idx[left]);
            left++;
        }

        // Find candidate y-range
        auto it = active.lower_bound(i);
        // Check upwards
        for (auto jt = it; jt != active.end(); ++jt) {
            int j = *jt;
            if (circles[j].y - circles[j].r >= circles[i].y + circles[i].r + best) break;
            best = min(best, dist(circles[i], circles[j]));
        }
        // Check downwards
        for (auto jt = it; jt != active.begin(); ) {
            --jt;
            int j = *jt;
            if (circles[j].y + circles[j].r <= circles[i].y - circles[i].r - best) break;
            best = min(best, dist(circles[i], circles[j]));
        }

        active.insert(i);
    }

    cout << fixed << setprecision(10) << best << "\n";
    return 0;
}

