#include <bits/stdc++.h>
using namespace std;

struct Circle {
    double x, y, r;
};

static inline double distCenters(const Circle& a, const Circle& b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    vector<Circle> c(N);
    for (int i = 0; i < N; ++i) {
        cin >> c[i].x >> c[i].y >> c[i].r;
    }

    if (N < 2) {
        cout << fixed << setprecision(10) << 0.0 << '\n';
        return 0;
    }

    // Since circles are non-overlapping and max radius <= 2 * min radius,
    // the closest pair of circles can be found by the closest pair of centers,
    // then subtracting the two radii.
    //
    // We use the standard O(N log N) closest-pair algorithm on centers.

    vector<int> ordX(N), ordY(N);
    iota(ordX.begin(), ordX.end(), 0);
    iota(ordY.begin(), ordY.end(), 0);

    sort(ordX.begin(), ordX.end(), [&](int i, int j) {
        if (c[i].x != c[j].x) return c[i].x < c[j].x;
        return c[i].y < c[j].y;
    });

    sort(ordY.begin(), ordY.end(), [&](int i, int j) {
        if (c[i].y != c[j].y) return c[i].y < c[j].y;
        return c[i].x < c[j].x;
    });

    function<pair<double, pair<int,int>>(const vector<int>&, const vector<int>&)> solve =
        [&](const vector<int>& px, const vector<int>& py) -> pair<double, pair<int,int>> {
            int n = (int)px.size();
            if (n <= 3) {
                double best = 1e300;
                pair<int,int> bestPair = {-1, -1};
                for (int i = 0; i < n; ++i) {
                    for (int j = i + 1; j < n; ++j) {
                        double d = distCenters(c[px[i]], c[px[j]]);
                        if (d < best) {
                            best = d;
                            bestPair = {px[i], px[j]};
                        }
                    }
                }
                return {best, bestPair};
            }

            int mid = n / 2;
            double midx = c[px[mid]].x;

            vector<int> lx(px.begin(), px.begin() + mid);
            vector<int> rx(px.begin() + mid, px.end());

            unordered_set<int> leftSet;
            leftSet.reserve(lx.size() * 2);
            for (int id : lx) leftSet.insert(id);

            vector<int> ly, ry;
            ly.reserve(lx.size());
            ry.reserve(rx.size());
            for (int id : py) {
                if (leftSet.count(id)) ly.push_back(id);
                else ry.push_back(id);
            }

            auto leftAns = solve(lx, ly);
            auto rightAns = solve(rx, ry);

            double d = leftAns.first;
            pair<int,int> bestPair = leftAns.second;
            if (rightAns.first < d) {
                d = rightAns.first;
                bestPair = rightAns.second;
            }

            vector<int> strip;
            for (int id : py) {
                if (fabs(c[id].x - midx) < d) strip.push_back(id);
            }

            int m = (int)strip.size();
            for (int i = 0; i < m; ++i) {
                for (int j = i + 1; j < m; ++j) {
                    if (c[strip[j]].y - c[strip[i]].y >= d) break;
                    double cur = distCenters(c[strip[i]], c[strip[j]]);
                    if (cur < d) {
                        d = cur;
                        bestPair = {strip[i], strip[j]};
                    }
                }
            }

            return {d, bestPair};
        };

    auto ans = solve(ordX, ordY);
    int i = ans.second.first;
    int j = ans.second.second;

    double circleDist = distCenters(c[i], c[j]) - c[i].r - c[j].r;
    if (circleDist < 0 && circleDist > -1e-12) circleDist = 0; // numerical safety

    cout << fixed << setprecision(10) << circleDist << '\n';
    return 0;
}

