public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        Circle[] circles = new Circle[N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            double x = Double.parseDouble(st.nextToken());
            double y = Double.parseDouble(st.nextToken());
            double r = Double.parseDouble(st.nextToken());
            circles[i] = new Circle(x, y, r);
        }

        // Sort by leftmost x
        Arrays.sort(circles, (a, b) -> Double.compare(a.left, b.left));

        // Active set sorted by y
        TreeSet<Circle> active = new TreeSet<>((a, b) -> {
            if (Math.abs(a.y - b.y) > 1e-12) return Double.compare(a.y, b.y);
            return Double.compare(a.x, b.x); // break ties by x
        });

        double best = Double.MAX_VALUE;
        int leftIdx = 0;

        for (int i = 0; i < N; i++) {
            Circle cur = circles[i];

            // Remove far left circles
            while (circles[leftIdx].right < cur.left - best) {
                active.remove(circles[leftIdx]);
                leftIdx++;
            }

            // Find candidates by y-range
            Circle lower = new Circle(0, cur.y - best, 0);
            Circle upper = new Circle(0, cur.y + best, 0);

            for (Circle other : active.subSet(lower, true, upper, true)) {
                double dist = distance(cur, other);
                if (dist < best) {
                    best = dist;
                }
            }

            active.add(cur);
        }

        System.out.printf("%.10f%n", best);
    }

    static double distance(Circle a, Circle b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.sqrt(dx*dx + dy*dy) - a.r - b.r;
    }

    static class Circle {
        double x, y, r, left, right;
        Circle(double x, double y, double r) {
            this.x = x;
            this.y = y;
            this.r = r;
            this.left = x - r;
            this.right = x + r;
        }
    }
}

