import java.io.*;
import java.util.*;

/*
Closest pair of circles.
Distance between circles i and j:
    max(0, distance(center_i, center_j) - r_i - r_j)
Since circles are guaranteed non-overlapping, this is simply:
    distance(center_i, center_j) - r_i - r_j >= 0

Key geometric fact:
Because circles are non-overlapping and max radius <= 2 * min radius,
the number of circles whose centers can lie in a small neighborhood is bounded by a constant.
Thus a standard sweep-line closest-pair approach works in O(N log N).

Algorithm:
1. Sort circles by x-coordinate of center.
2. Maintain active circles in a TreeSet ordered by y-coordinate.
3. Let best be the smallest circle distance found so far.
   If for two circles to improve best, then center distance < best + r1 + r2 <= best + 2*Rmax.
   Since Rmax <= 2*Rmin and radii are within factor 2, using the exact test on candidates
   while sweeping with x-window based on best + ri + Rmax is sufficient.
4. Remove circles too far in x to improve best.
5. Query active set for circles with y within a corresponding bound and test exactly.

This remains efficient because candidate density is constant under the given radius ratio
and non-overlap constraints.

Input format assumed:
N
x1 y1 r1
...
xN yN rN

Output:
minimum distance between any pair of circles

Printed with 10 digits after decimal point.
*/

public class Main {
    static class Circle {
        double x, y, r;
        int id;
        Circle(double x, double y, double r, int id) {
            this.x = x;
            this.y = y;
            this.r = r;
            this.id = id;
        }
    }

    static double circleDistance(Circle a, Circle b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.sqrt(dx * dx + dy * dy) - a.r - b.r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        Circle[] circles = new Circle[n];
        double maxR = 0.0;

        for (int i = 0; i < n; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            double r = fs.nextDouble();
            circles[i] = new Circle(x, y, r, i);
            maxR = Math.max(maxR, r);
        }

        if (n < 2) {
            System.out.printf(Locale.US, "0.0000000000%n");
            return;
        }

        Arrays.sort(circles, (a, b) -> {
            int cmp = Double.compare(a.x, b.x);
            if (cmp != 0) return cmp;
            cmp = Double.compare(a.y, b.y);
            if (cmp != 0) return cmp;
            return Integer.compare(a.id, b.id);
        });

        TreeSet<Circle> active = new TreeSet<>((a, b) -> {
            int cmp = Double.compare(a.y, b.y);
            if (cmp != 0) return cmp;
            cmp = Double.compare(a.x, b.x);
            if (cmp != 0) return cmp;
            return Integer.compare(a.id, b.id);
        });

        double best = Double.POSITIVE_INFINITY;
        int left = 0;

        for (int i = 0; i < n; i++) {
            Circle cur = circles[i];

            // Remove circles too far in x to beat current best.
            while (left < i) {
                Circle old = circles[left];
                // Minimum possible center x-gap needed to improve best:
                // if dx > best + old.r + cur.r then impossible for this cur,
                // but cur.r varies. Use safe larger bound with maxR.
                if (cur.x - old.x > best + old.r + maxR) {
                    active.remove(old);
                    left++;
                } else {
                    break;
                }
            }

            // Candidates must also be close in y.
            double yRange = (Double.isInfinite(best) ? Double.POSITIVE_INFINITY : best + cur.r + maxR);

            Circle from = new Circle(Double.NEGATIVE_INFINITY, cur.y - yRange, 0, -1);
            Circle to   = new Circle(Double.POSITIVE_INFINITY, cur.y + yRange, 0, Integer.MAX_VALUE);

            for (Circle cand : active.subSet(from, true, to, true)) {
                double d = circleDistance(cur, cand);
                if (d < best) best = d;
            }

            active.add(cur);
        }

        if (best < 0 && best > -1e-12) best = 0; // guard against precision noise
        System.out.printf(Locale.US, "%.10f%n", best);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}
